function icon(name, cls=''){ return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.leaf}"/></svg>`; }
const state = {user:null,guest:false,profile:{},plants:[],analyses:[],source:'cloud',dataError:'',scanPhoto:'',scanSymptoms:[],scanNotes:'',scanPlantId:'',scanMethod:'',draft:null,plantPhoto:null,profilePhoto:null,model:null};
let unsubscribeData=()=>{}, cameraStream=null, cameraFacing='environment', toastTimer, authResolved=false, modelLoadController=null, scanLoadController=null;
let lastRenderedRoute='';
const pendingForms=new Set();
const ACCESS_MODE_KEY='ecoplant-access-mode';
function accessMode(){try{return localStorage.getItem(ACCESS_MODE_KEY)||'';}catch{return '';}}
function rememberAccessMode(mode){try{localStorage.setItem(ACCESS_MODE_KEY,mode);}catch{/* The current session remains usable if preferences cannot be stored. */}}
const blankData = () => ({profile:{},plants:[],analyses:[]});
const date = value => { const d=new Date(value||Date.now()); return isNaN(d)?'Data indisponível':new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/Sao_Paulo'}).format(d); };
const name = () => state.profile.displayName || state.profile.name || state.user?.displayName || 'Seu jardim';
const firstName = () => name().split(' ')[0];
const currentRoute = () => (location.hash || (state.user?'#home':'#login')).slice(1);
const routePath = () => currentRoute().split('?')[0];
const routeParams = () => new URLSearchParams(currentRoute().split('?')[1] || '');
const findPlant = id => state.plants.find(p => p.id===id);
const sortedAnalyses = () => [...state.analyses].sort((a,b)=>Number(b.date||b.createdAt)-Number(a.date||a.createdAt));
const latest = id => sortedAnalyses().find(a=>a.plantId===id);
const photoSafe = value => typeof value==='string' && /^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value) ? value : '';
function avatar(size=''){const photo=photoSafe(state.profile.photo);return `<span class="avatar ${size}">${photo?`<img src="${esc(photo)}" alt="Foto de perfil">`:esc(firstName().slice(0,1).toUpperCase())}</span>`;}
function brand(){return `<a class="brand" href="${state.user?'#home':'#login'}"><img class="brand-logo" src="./assets/ecoplant-logo.png" width="44" height="44" alt="Logo Ecoplant"><span><strong>Ecoplant</strong><small>CUIDAR É OBSERVAR</small></span></a>`;}
function go(hash){if(location.hash===hash)render();else location.hash=hash;}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',error?6500:3600);}
function errorMessage(error){return error?.userMessage || (/^(model|classifier|plant-ai)\//.test(error?.code||'')?error.message:cloud.readableError(error));}
function activeModelURL(){return state.model?.source==='files'?IMPORTED_MODEL_URL:state.profile.modelURL||(MODEL_CONFIG.bundledModelAvailable?BUNDLED_MODEL_URL:'');}
function activeModelSource(){return state.model?.source==='files'?'files':state.profile.modelURL?'hosted':MODEL_CONFIG.bundledModelAvailable?'bundled':'none';}
function modelIsReady(){try{return !!state.model&&state.model.modelURL===validateModelURL(activeModelURL());}catch{return false;}}
function syncModelSource(){
 const form=$('#model-form');if(!form)return;
 const source=form.elements.modelSource.value;
 const healthyField=form.elements.healthyClass;healthyField.disabled=false;healthyField.closest('.field').classList.remove('hidden');form.querySelector('[data-healthy-help]').classList.remove('hidden');
 for(const panel of form.querySelectorAll('[data-model-source]')){
  const active=panel.dataset.modelSource===source;panel.hidden=!active;
  for(const input of panel.querySelectorAll('input')){input.disabled=!active;input.required=active;}
 }
}
function modelSettingsView(){
 const p=state.profile,requested=routeParams().get('model'),active=activeModelSource(),source=['files','hosted'].includes(requested)?requested:active==='none'?'files':active,ready=modelIsReady();
 return `<section class="panel form-panel"><div class="eyebrow" style="margin-bottom:10px">INTELIGÊNCIA TREINADA POR VOCÊ</div><h2 class="serif">Teachable Machine</h2>
 <p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:22px">A IA de imagem já está disponível em Analisar planta. Aqui você pode conectar um treinamento próprio do Teachable Machine.</p>
 ${!activeModelURL()?'<div class="notice amber" style="margin-bottom:18px"><span>Seu modelo próprio ainda não foi conectado. A IA pronta para usar continua disponível na tela Analisar planta.</span></div>':''}
 <form id="model-form">
  <label class="field" for="model-source">Origem do modelo<select id="model-source" name="modelSource">
   <option value="bundled" ${MODEL_CONFIG.bundledModelAvailable?'':'disabled'} ${source==='bundled'?'selected':''}>Modelo do EcoPlant${MODEL_CONFIG.bundledModelAvailable?'':' — aguardando arquivos'}</option>
   <option value="hosted" ${source==='hosted'?'selected':''}>Link do Teachable Machine</option>
   <option value="files" ${source==='files'?'selected':''}>Arquivos do modelo</option>
  </select></label>
  <div data-model-source="bundled" ${source==='bundled'?'':'hidden'}><div class="notice" style="margin-bottom:18px"><span>Carrega os arquivos de treinamento publicados junto com o EcoPlant.</span></div></div>
  <div data-model-source="hosted" ${source==='hosted'?'':'hidden'}>${field('Link do modelo publicado','modelURL','https://teachablemachine.withgoogle.com/models/SEU_ID/',{type:'url',maxlength:300,value:p.modelURL||''})}</div>
  <div data-model-source="files" ${source==='files'?'':'hidden'}><label class="field" for="model-files">Arquivos exportados do Teachable Machine<input id="model-files" name="modelFiles" type="file" accept=".json,.bin" multiple></label><p class="privacy-note" style="margin-bottom:18px">Descompacte o ZIP e selecione juntos <strong>model.json</strong>, <strong>metadata.json</strong> e todos os arquivos <strong>.bin</strong> dos pesos. Eles são usados somente nesta aba e precisam ser selecionados novamente após recarregar. Não são enviados ao banco de dados.</p></div>
  ${field('Nome exato da classe saudável (opcional)','healthyClass','Ex.: Saudável',{maxlength:200,value:source==='files'?(state.model?.source==='files'?state.model.healthyClass||'':''):p.healthyClass||''})}
  <p class="privacy-note" data-healthy-help>Informe uma classe que exista no treinamento. A confiança indica a escolha do modelo, não a gravidade de uma doença.</p>
  <div class="form-error" role="alert"></div><button class="btn block" type="submit">${icon('spark')}Carregar e usar modelo</button>
  ${state.model?.source==='files'||p.modelURL?`<button class="link" type="button" data-action="remove-model" style="margin-top:12px">${MODEL_CONFIG.bundledModelAvailable?'Voltar ao modelo do EcoPlant':'Desconectar modelo'}</button>`:''}
  <div id="model-status" class="notice ${ready?'':'hidden'}" role="status" aria-live="polite">${ready?esc('Modelo carregado · '+state.model.labels.length+' classes: '+state.model.labels.slice(0,6).join(', ')+(state.model.labels.length>6?'…':'')):''}</div>
 </form>
 <div class="tips-item" style="margin-top:25px">${icon('camera')}<div><h3>Seu treinamento faz a diferença</h3><p>Inclua diferentes folhas, fundos e iluminações. Separe fotos novas para verificar o desempenho antes de usar os resultados.</p></div></div><a class="link" href="https://teachablemachine.withgoogle.com/train/image" target="_blank" rel="noopener noreferrer" style="display:inline-block;margin-top:16px">Abrir Teachable Machine ↗</a></section>`;
}
function openDialog(title,html){const d=$('#dialog');stopCamera();d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Fechar">${icon('close')}</button></div>${html}`;d.showModal();return d;}
function closeDialog(){stopCamera();$('#dialog').close();}
function authScreen(view){
 const register=view==='register',recover=view==='recover';
 return `<main class="auth"><aside class="auth-story">${brand()}<h2 class="serif">Um olhar atento.<br>Uma planta <i>mais saudável.</i></h2><p>Fotografe, descubra os sinais e acompanhe cada nova folha do seu jardim.</p><img src="./assets/garden.svg" alt="Ilustração botânica de uma planta em vaso"><footer><span>TECNOLOGIA A SERVIÇO DO VERDE</span><span>01 / SEU JARDIM COMEÇA AQUI</span></footer></aside><section class="auth-panel"><div class="auth-tools">${renderThemeSwitch()}<button class="auth-install btn secondary small" data-action="install" aria-label="Instalar Ecoplant">${icon('download')} Instalar Ecoplant</button></div><div class="auth-inner"><div class="eyebrow">${recover?'VAMOS RECUPERAR SEU ACESSO':register?'CULTIVE NOVOS HÁBITOS':'BEM-VINDO AO SEU JARDIM'}</div><h1 class="serif">${recover?'Esqueceu a senha?':register?'Crie sua conta.':'Bom te ver de novo.'}</h1><p class="intro">${recover?'Informe seu e-mail para receber o link de recuperação.':register?'Um espaço para suas plantas e para tudo o que você aprende com elas.':'Entre para acompanhar suas plantas, do primeiro registro à próxima folha.'}</p>${!register&&!recover?`<section class="auth-quick-start" aria-label="Começar sem conta"><button class="btn block" type="button" data-action="guest" data-destination="#scan">${icon('camera')}Analisar uma planta sem conta</button><p>Envie uma foto e receba o relatório. Seus registros ficam neste aparelho.</p></section>`:''}<form id="auth-form" data-view="${esc(view)}">${register?field('Nome completo','name','Seu nome',{required:true,maxlength:120,autocomplete:'name'}):''}${field('E-mail','email','voce@exemplo.com',{type:'email',required:true,autocomplete:'email'})}${recover?'':passwordField('Senha','password',register?'Crie uma senha com 8 ou mais caracteres':'Sua senha',register?'new-password':'current-password',register?8:1)}${register?passwordField('Confirmar senha','confirm','Repita a senha','new-password',8):''}${!recover?`<div class="auth-options"><label class="checkbox"><input type="checkbox" name="remember" checked>Manter conectado</label>${!register?'<a class="link" href="#recover">Esqueci minha senha</a>':''}</div>`:''}<div class="form-error" role="alert"></div><button class="btn block" type="submit">${icon(recover?'mail':register?'user':'arrow')}${recover?'Enviar link':register?'Criar conta':'Entrar'}</button></form>${!recover?`<div class="divider">OU CONTINUE COM</div><button class="btn secondary block" data-action="google"><span class="google-g" aria-hidden="true">G</span>Continuar com Google</button>`:''}<p class="auth-switch">${recover?'<a href="#login">Voltar ao login</a>':register?'Já tem uma conta? <a href="#login">Entrar</a>':'Novo por aqui? <a href="#register">Criar uma conta</a>'}</p><div class="guest-link"><button class="link" data-action="guest">Continuar neste aparelho</button><small>Sem conta, os dados ficam apenas neste dispositivo.</small></div>${register?'<p class="privacy-note" style="margin-top:20px">Ao criar a conta, você permite guardar seu perfil e seus registros de plantas. Suas fotos ficam acessíveis à sua própria conta.</p>':''}</div></section></main>`;
}
function field(label,id,placeholder='',opts={}){const value=opts.value??'';const attrs=Object.entries(opts).filter(([k])=>k!=='value'&&k!=='type').map(([k,v])=>v===true?esc(k):`${esc(k)}="${esc(v)}"`).join(' ');return `<label class="field" for="${esc(id)}">${esc(label)}<input id="${esc(id)}" name="${esc(id)}" type="${esc(opts.type||'text')}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${attrs}></label>`;}
function passwordField(label,id,placeholder,autocomplete,min){return `<label class="field" for="${id}">${label}<span class="password-field"><input id="${id}" name="${id}" type="password" placeholder="${esc(placeholder)}" autocomplete="${autocomplete}" required minlength="${min}" maxlength="128"><button type="button" data-action="toggle-password" data-target="${id}" aria-label="Mostrar senha">${icon('eye')}</button></span></label>`;}
function navLink(href,label,ico,active){return `<a class="nav-link ${active?'active':''}" href="${href}">${icon(ico)}${label}${href==='#plants'&&state.plants.length?`<span class="nav-count">${state.plants.length}</span>`:''}</a>`;}
function shell(content,active='home',title='Visão geral'){
 const local=state.guest,offline=navigator.onLine===false;
 return `<div class="shell"><aside class="sidebar">${brand()}<div class="eyebrow">MEU JARDIM</div><nav>${navLink('#home','Visão geral','home',active==='home')}${navLink('#plants','Minhas plantas','plants',active==='plants')}${navLink('#history','Histórico','clock',active==='history')}${navLink('#profile','Meu perfil','user',active==='profile')}${navLink('#guide','Como usar','help',active==='guide')}</nav><div class="sidebar-bottom"><div class="install-tile">${icon('download')}<h3>Seu jardim, com você.</h3><p>${isStandalone()?'O Ecoplant já está instalado neste aparelho.':'Instale o Ecoplant na tela inicial e fique mais perto das suas plantas.'}</p><button class="btn secondary small" data-action="install">${isStandalone()?'Sobre a instalação':'Instalar aplicativo'}</button></div><a href="#profile" class="sidebar-user">${avatar()}<span><strong>${esc(name())}</strong><small>${local?'Dados neste aparelho':'Minha conta Ecoplant'}</small></span></a></div></aside><header class="topbar"><div class="breadcrumb">${icon('home')} Meu jardim <span>/</span><span>${esc(title)}</span></div><a href="#home" class="mobile-brand"><img class="mobile-logo" src="./assets/ecoplant-logo.png" width="36" height="36" alt="Logo Ecoplant"><strong>Ecoplant</strong></a><div class="topbar-right">${renderThemeSwitch()}<span class="date">${date(Date.now())}</span><span class="status-pill ${local||offline?'local':''}"><span class="status-dot"></span>${offline?'Sem conexão':local?'Neste aparelho':state.dataError?'Sincronização pendente':state.source==='cache'?'Última sincronização':'Minha conta'}</span><a href="#profile" aria-label="Meu perfil">${avatar()}</a></div></header><main class="content">${state.dataError?`<div class="notice amber app-banner">${icon('info')}<span>${esc(state.dataError)} <button class="link" data-action="retry-sync">Tentar novamente</button></span></div>`:''}${offline?`<div class="notice app-banner">${icon('info')}<span>Você está offline. Os últimos registros consultados continuam disponíveis.${state.guest?'':' Reconecte para salvar na sua conta.'}</span></div>`:''}${content}<div class="footer-caption">ECOPLANT · CADA FOLHA CONTA UMA HISTÓRIA</div></main><nav class="mobile-nav" aria-label="Navegação principal"><a href="#home" class="${active==='home'?'active':''}">${icon('home')}Início</a><a href="#plants" class="${active==='plants'?'active':''}">${icon('plants')}Plantas</a><a href="#scan" class="scan-nav" aria-label="Fotografar planta">${icon('camera')}</a><a href="#history" class="${active==='history'?'active':''}">${icon('clock')}Histórico</a><a href="#profile" class="${active==='profile'?'active':''}">${icon('user')}Perfil</a></nav></div>`;
}
function heading(eyebrow,title,description='',action=''){return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 class="serif">${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>${action}</div>`;}
function empty(ico,title,copy,href,label){return `<div class="empty-state"><span class="empty-icon">${icon(ico)}</span><h3>${esc(title)}</h3><p>${esc(copy)}</p>${href?`<a class="btn secondary small" href="${esc(href)}">${icon('plus')}${esc(label)}</a>`:''}</div>`;}
function healthBadge(result, fallback='Sem análise por IA'){
 const health=describePlantHealth(result),assessed=health.status!=='unassessed';
 return `<span class="health-badge health-${assessed?health.tone:'neutral'}">${icon(health.status==='healthy'?'check':health.status==='disease'||health.status==='pest'?'info':'help')}${esc(assessed?health.shortLabel:fallback)}</span>`;
}
function plantHealthPanel(record){
 if(!record)return '';
 const health=describePlantHealth(record.result);
 if(health.status==='unassessed')return '';
 return `<section class="plant-health-panel health-${health.tone}" aria-label="Resultado da última foto"><div class="eyebrow">ÚLTIMA FOTO ANALISADA · ${date(record.date||record.createdAt)}</div>${healthBadge(record.result)}<h3>${esc(health.title)}</h3>${health.condition&&health.status!=='healthy'?`<p class="health-condition"><strong>${health.status==='pest'?'Possível praga':'Possível doença'}:</strong> ${esc(health.condition)}</p>`:''}<p>${esc(health.summary)}</p><a class="link" href="#report/${esc(record.id)}">Ver relatório completo ${icon('right')}</a></section>`;
}
function plantCard(p){const photo=photoSafe(p.photo),last=latest(p.id);return `<article class="plant-card" data-plant-search="${esc((p.name+' '+(p.species||'')+' '+(p.location||'')).toLocaleLowerCase('pt-BR'))}"><a href="#plant/${esc(p.id)}">${photo?`<img class="plant-photo" src="${esc(photo)}" alt="${esc(p.name)}" loading="lazy">`:'<div class="plant-placeholder"><img src="./assets/garden.svg" alt="Ilustração de planta"></div>'}<div class="plant-body"><h3>${esc(p.name)}</h3><p class="species">${esc(p.species||'Espécie não informada')}</p><div class="plant-meta"><span>${icon('pin')}${esc(p.location||'Meu jardim')}</span>${healthBadge(last?.result,last?(last.result?.method==='teachable-machine'?'Modelo personalizado':'Registro sem IA'):'Ainda não avaliada')}</div>${last?`<p class="health-date">Última foto · ${date(last.date||last.createdAt)}</p>`:''}</div></a></article>`;}
function recordCard(a){
 const p=findPlant(a.plantId),photo=photoSafe(a.photo),health=describePlantHealth(a.result),assessed=health.status!=='unassessed';
 const label=assessed?(health.status==='inconclusive'?health.title:[health.crop,health.condition].filter(Boolean).join(' · ')||health.title):(a.result?.title||a.result?.topClass||'Registro de observação');
 return `<a class="record" href="#report/${esc(a.id)}">${photo?`<img class="record-thumb" src="${esc(photo)}" alt="Foto do registro" loading="lazy">`:`<span class="record-thumb">${icon('leaf')}</span>`}<div class="record-info">${assessed?healthBadge(a.result):''}<h3>${esc(label)}</h3><p>${esc(p?.name||'Planta da foto')} · ${a.result?.method==='plant-ai'?'Análise por IA':a.result?.method==='teachable-machine'?'Teachable Machine':'Relatório de observação'}</p><time>${date(a.date||a.createdAt)}</time></div>${icon('right')}</a>`;
}
function followUpReminder(){if(state.profile.reminders===false)return '';const plant=state.plants.find(p=>{const record=latest(p.id);return record&&Date.now()-Number(record.date||record.createdAt)>3*24*60*60*1000;});return plant?`<div class="notice app-banner">${icon('clock')}<span>Que tal observar ${esc(plant.name)} novamente? Seu último registro tem mais de três dias. <a class="link" href="#scan?plant=${esc(plant.id)}">Fazer um novo registro</a></span></div>`:'';}
function home(){const now=new Date().getHours(),greeting=now<12?'Bom dia':now<18?'Boa tarde':'Boa noite';const recent=sortedAnalyses().slice(0,3);return shell(`${heading('UM NOVO DIA PARA CULTIVAR',['Meu jardim','Seu jardim'].includes(name())?'Bem-vindo ao seu jardim.':`${greeting}, ${firstName()}.`,'Que tal observar suas plantas hoje?',`<a class="btn" href="#plant/new">${icon('plus')}Nova planta</a>`)}${followUpReminder()}<section class="hero"><div class="hero-text"><div class="eyebrow">${icon('spark')} UM OLHAR MAIS DE PERTO</div><h2 class="serif">Sua planta tem<br>algo a contar.</h2><p>Veja se a folha tem aparência saudável ou sinais de possíveis doenças e pragas.</p><a href="#scan" class="btn">${icon('camera')}Analisar minha planta</a></div><img class="hero-image" src="./assets/garden.svg" alt="Planta em vaso com folhas verdes"><span class="hero-tag">Cuidar começa por observar</span></section><div class="stats"><div class="stat"><span class="stat-icon">${icon('plants')}</span><div><strong>${state.plants.length}</strong><p>Plantas no jardim</p></div></div><div class="stat"><span class="stat-icon">${icon('file')}</span><div><strong>${state.analyses.length}</strong><p>Registros salvos</p></div></div><div class="stat"><span class="stat-icon">${icon('camera')}</span><div><strong>${new Set(state.analyses.map(a=>a.plantId).filter(Boolean)).size}</strong><p>Em acompanhamento</p></div></div></div><div class="home-grid"><section><div class="section-head"><h2>Seu pequeno jardim</h2><a class="link" href="#plants">Ver todas</a></div>${state.plants.length?`<div class="plant-grid">${state.plants.slice(0,2).map(plantCard).join('')}</div>`:`<div class="panel">${empty('plants','O primeiro broto é seu.','Adicione uma planta para guardar fotos, observações e relatórios.','#plant/new','Adicionar primeira planta')}</div>`}</section><section><div class="section-head"><h2>Para observar melhor</h2><a class="link" href="#guide">Como funciona</a></div><div class="panel"><div class="tips-item">${icon('sun')}<div><h3>Boa luz faz a diferença</h3><p>Prefira iluminação natural e evite sombras sobre a folha.</p></div></div><div class="tips-item">${icon('camera')}<div><h3>Uma folha por vez</h3><p>Mostre os detalhes e mantenha a câmera firme e próxima.</p></div></div><div class="tips-item">${icon('clock')}<div><h3>Observe ao longo dos dias</h3><p>Use fotos com o mesmo enquadramento para comparar os registros.</p></div></div></div></section></div>${recent.length?`<section style="margin-top:30px"><div class="section-head"><h2>Últimos registros</h2><a href="#history" class="link">Ver histórico</a></div><div class="timeline">${recent.map(recordCard).join('')}</div></section>`:''}`);}
function plantsView(){return shell(`${heading('CADA PLANTA, UMA HISTÓRIA','Minhas plantas','Um espaço para conhecer e cuidar do seu jardim.',`<a class="btn" href="#plant/new">${icon('plus')}Adicionar planta</a>`)}${state.plants.length?`<div class="toolbar"><label class="search">${icon('search')}<input data-search placeholder="Buscar por nome, espécie ou local" aria-label="Buscar plantas"></label><span>${state.plants.length} planta${state.plants.length>1?'s':''} no jardim</span></div><div class="plant-grid">${state.plants.map(plantCard).join('')}</div><p id="search-empty" class="muted hidden" style="padding:30px;text-align:center;font-size:12px">Nenhuma planta encontrada.</p>`:`<div class="panel">${empty('plants','Seu jardim começa aqui','Dê um nome à sua planta e adicione a primeira foto.','#plant/new','Cadastrar uma planta')}</div>`}`,'plants','Minhas plantas');}
function plantForm(id){const p=id?findPlant(id):null;if(id&&!p)return missing();const photo=state.plantPhoto??p?.photo;return shell(`${heading('UM NOVO CAPÍTULO NO JARDIM',p?'Editar planta':'Nova planta','Guarde os detalhes que tornam essa planta única.')}<div class="form-layout"><section class="panel form-panel"><form id="plant-form" data-id="${esc(id||'')}"><label class="upload-box ${photoSafe(photo)?'has-photo':''}" for="plant-photo-input">${photoSafe(photo)?`<img src="${esc(photo)}" alt="Foto da planta"><span class="upload-label">Trocar foto</span>`:`${icon('camera')}<span><h3>Adicionar uma foto</h3><p>Uma boa foto ajuda a acompanhar a evolução.</p></span>`}<input id="plant-photo-input" type="file" accept="image/*" data-upload="plant" hidden></label><div class="photo-controls"><button id="plant-image-button" type="button" class="btn secondary" data-action="choose-photo" data-target="plant-photo-input">${icon('gallery')}${photoSafe(photo)?'Trocar imagem':'Enviar imagem'}</button></div><p class="privacy-note" style="margin:10px 0 18px">Escolha uma imagem do computador ou da galeria do celular. JPG, PNG ou WebP, até 15 MB. A foto será gravada ao salvar a planta.</p>${photoSafe(photo)?'<button type="button" class="link" data-action="remove-plant-photo">Remover foto</button>':''}${field('Nome da planta','plant-name','Ex.: Meu tomateiro',{required:true,maxlength:120,value:p?.name})}<div class="form-grid">${field('Espécie (opcional)','species','Ex.: Solanum lycopersicum',{maxlength:180,value:p?.species})}${field('Local de cultivo (opcional)','location','Ex.: Horta de casa',{maxlength:180,value:p?.location})}</div><label class="field">Observações (opcional)<textarea name="notes" maxlength="4000" placeholder="Anote os detalhes da sua planta">${esc(p?.notes||'')}</textarea></label><div class="form-error" role="alert"></div><div class="form-actions"><button type="submit" class="btn">${icon('check')}Salvar planta</button><a class="btn secondary" href="${p?'#plant/'+esc(p.id):'#plants'}">Cancelar</a></div></form></section><aside class="info-aside"><img src="./assets/garden.svg" alt="Ilustração botânica"><div class="eyebrow">PRIMEIRO, CONHECER</div><h3>Cada detalhe importa.</h3><p>Registre o local, a espécie e as mudanças que você percebe. Seu histórico ajuda a acompanhar o desenvolvimento da planta.</p></aside></div>`,'plants',p?'Editar planta':'Cadastrar planta');}
function plantDetail(id){const p=findPlant(id);if(!p)return missing();const records=sortedAnalyses().filter(a=>a.plantId===id);const photo=photoSafe(p.photo);return shell(`${heading(p.species||'MEU JARDIM',p.name,p.location||'Sua planta no Ecoplant',`<a class="btn secondary small" href="#plant/${esc(id)}/edit">${icon('edit')}Editar</a>`)}<div class="detail-layout"><section><div class="detail-photo ${photo?'':'placeholder'}"><img src="${photo?esc(photo):'./assets/garden.svg'}" alt="${esc(p.name)}"></div><div class="detail-info"><span class="badge">${icon('plants')}${records.length} registro${records.length===1?'':'s'}</span><dl><dt>No jardim desde</dt><dd>${date(p.createdAt)}</dd><dt>Local</dt><dd>${esc(p.location||'Não informado')}</dd><dt>Espécie</dt><dd>${esc(p.species||'Não informada')}</dd></dl>${p.notes?`<p class="detail-notes">${esc(p.notes)}</p>`:''}<button class="link" data-action="delete-plant" data-id="${esc(id)}" style="margin-top:25px;color:var(--red)">Excluir planta e registros</button></div></section><section>${plantHealthPanel(records[0])}<div class="section-head"><h2>Uma folha de cada vez</h2></div>${photo?`<button class="btn block" type="button" data-action="analyze-plant-photo" data-id="${esc(id)}">${icon('spark')}Gerar relatório com esta foto</button>`:''}<button class="btn ${photo?'secondary':''} block" style="margin-top:10px" type="button" data-action="new-plant-analysis" data-id="${esc(id)}">${icon('camera')}Analisar uma nova foto</button><div class="section-head" style="margin-top:27px"><h2>Histórico da planta</h2>${records.length>1?`<button class="link" data-action="compare" data-id="${esc(id)}">Comparar fotos</button>`:''}</div>${records.length?`<div class="timeline">${records.map(recordCard).join('')}</div>`:`<div class="panel">${empty('clock','Ainda sem registros','Fotografe uma folha para começar o acompanhamento.','','')}</div>`}</section></div>`,'plants',p.name);}
function historyView(){return shell(`${heading('O TEMPO TAMBÉM CUIDA','Histórico','Confira o resultado de cada foto e acompanhe possíveis mudanças.',`<a class="btn" href="#scan">${icon('camera')}Novo registro</a>`)}${state.analyses.length?`<div class="toolbar history-toolbar"><label class="field">Filtrar por planta<select id="history-filter"><option value="">Todas as plantas</option>${state.plants.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label class="field">Filtrar por resultado<select id="history-health-filter"><option value="">Todos os resultados</option><option value="healthy">Aparência saudável</option><option value="disease">Possível doença</option><option value="pest">Possível praga</option><option value="inconclusive">Inconclusivo</option><option value="unassessed">Outros registros</option></select></label><span>${state.analyses.length} registros salvos</span></div><div class="timeline">${sortedAnalyses().map(a=>`<div data-record-plant="${esc(a.plantId||'')}" data-record-health="${describePlantHealth(a.result).status}">${recordCard(a)}</div>`).join('')}</div><p id="history-empty" class="muted" hidden>Nenhum registro corresponde aos filtros escolhidos.</p>`:`<div class="panel">${empty('clock','A história ainda vai começar','Seus registros e relatórios aparecerão aqui após a primeira avaliação.','#scan','Analisar uma folha')}</div>`}`,'history','Histórico');}
function filterHistory(){
 const plant=$('#history-filter')?.value||'',health=$('#history-health-filter')?.value||'';
 let visible=0;
 for(const row of document.querySelectorAll('[data-record-plant]')){row.hidden=!!((plant&&row.dataset.recordPlant!==plant)||(health&&row.dataset.recordHealth!==health));if(!row.hidden)visible++;}
 const empty=$('#history-empty');if(empty)empty.hidden=visible>0;
}
function scanView(){
 const requested=state.scanPlantId||routeParams().get('plant')||'',chosen=findPlant(requested)?requested:'',hasTM=!!activeModelURL();
 const method=['plant-ai','guided','teachable-machine'].includes(state.scanMethod)&&(state.scanMethod!=='teachable-machine'||hasTM)?state.scanMethod:'plant-ai';
 const photo=photoSafe(state.scanPhoto);
 return shell(`${heading('SAÚDE DA PLANTA','Sua planta parece saudável?','Envie uma foto de uma folha para verificar sua aparência e investigar possíveis doenças ou pragas.')}<div class="scan-layout"><section>
  <div class="scan-step">01 / A FOTO DA FOLHA</div><div class="scan-photo">${photo?`<img src="${esc(photo)}" alt="Folha selecionada para avaliação">`:`<div class="scan-placeholder">${icon('camera')}<h3>Vamos observar uma folha?</h3><p>Fotografe uma única folha, com boa luz e fundo simples.</p></div>`}</div>
  <div class="photo-controls"><button class="btn" data-action="open-camera">${icon('camera')}Abrir câmera</button><button id="scan-image-button" type="button" class="btn secondary" data-action="choose-photo" data-target="scan-photo-input">${icon('gallery')}${photo?'Trocar imagem':'Enviar imagem'}</button><input id="scan-photo-input" type="file" accept="image/*" data-upload="scan" hidden></div>
  <input type="file" id="camera-fallback" accept="image/*" capture="environment" data-upload="scan" hidden>
  <p class="privacy-note" style="margin:12px 0">Escolha uma imagem do computador ou da galeria do celular. JPG, PNG ou WebP, até 15 MB.</p>
  <div id="scan-ready" class="notice ${photo?'':'hidden'}" role="status" aria-live="polite">${icon('check')}<span>Foto pronta. Toque em Analisar com IA e gerar relatório para verificar a folha.</span></div>
  <div class="notice" style="margin-top:14px">${icon('info')}<span>A análise por IA acontece neste navegador. A foto só é gravada no histórico quando você salva o relatório.</span></div>
 </section><section class="panel scan-panel"><div class="scan-step">02 / GERAR SEU RELATÓRIO</div>
 <form id="scan-form" novalidate>
  <label class="field">Vincular a uma planta (opcional)<select name="plantId"><option value="" ${chosen?'':'selected'}>Somente esta foto</option>${state.plants.map(p=>`<option value="${esc(p.id)}" ${p.id===chosen?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>
  <label class="field">Como deseja gerar o relatório?<select name="method" id="analysis-method">
   <option value="plant-ai" ${method==='plant-ai'?'selected':''}>IA de imagem — pronta para usar</option>
   <option value="guided" ${method==='guided'?'selected':''}>Relatório de observação — sem IA</option>
   <option value="teachable-machine" ${hasTM?'':'disabled'} ${method==='teachable-machine'?'selected':''}>Meu modelo do Teachable Machine${hasTM?'':' — conectar no perfil'}</option>
  </select></label>
  <div class="health-explainer scan-method-note" data-scan-method="plant-ai" ${method==='plant-ai'?'':'hidden'}><strong>Uma conclusão clara sobre a folha</strong><ul><li><span class="health-badge health-healthy">${icon('check')}Aparência saudável</span></li><li><span class="health-badge health-danger">${icon('info')}Possível doença ou praga</span></li><li><span class="health-badge health-neutral">${icon('help')}Inconclusivo</span></li></ul><p>A IA mostra o nome da possível doença ou praga e os próximos cuidados. Se não houver informação suficiente, pede outra foto.</p><small>Sem chave ou treinamento. Modelo com 38 classes de 14 culturas. Primeiro uso: cerca de 24 MB, além do mecanismo de processamento.</small></div>
  <div class="notice scan-method-note" data-scan-method="guided" ${method==='guided'?'':'hidden'}><span>Gera um registro com sua foto e observações. Os sinais são opcionais; a imagem não é interpretada por IA neste modo.</span></div>
  <div class="notice scan-method-note" data-scan-method="teachable-machine" ${method==='teachable-machine'?'':'hidden'}><span>Usa as classes do treinamento que você conectou no perfil. ${modelIsReady()?'Modelo carregado e pronto.':'O modelo será carregado antes da análise.'}</span></div>
  <details class="scan-details"><summary>Sinais que observei (opcional)</summary><div class="symptom-grid">${SYMPTOMS.map(x=>`<label class="symptom"><input type="checkbox" name="symptom" value="${esc(x.id)}" ${state.scanSymptoms.includes(x.id)?'checked':''}>${esc(x.label)}</label>`).join('')}</div></details>
  <label class="field">Suas observações (opcional)<textarea name="notes" maxlength="4000" placeholder="Quando os sinais apareceram? O que mudou nos cuidados?">${esc(state.scanNotes)}</textarea></label>
  <div class="form-error scan-error" role="alert" tabindex="-1"></div>
  <button id="scan-submit" class="btn block" type="submit">${icon('spark')}${method==='guided'?'Gerar relatório de observação':method==='teachable-machine'?'Analisar com meu modelo e gerar relatório':'Analisar com IA e gerar relatório'}</button>
  <button class="btn secondary block" type="button" data-action="observation-report" style="margin-top:10px" ${method==='guided'?'hidden':''}>${icon('file')}Gerar relatório sem IA</button>
  <div id="model-recovery" class="form-actions hidden" style="margin-top:14px"><button class="link" type="button" data-action="retry-analysis">Tentar a análise novamente</button><a class="link" href="#profile?model=files" data-tm-recovery>Conectar meu modelo</a></div>
  <p class="privacy-note" style="margin-top:14px">O relatório abre nesta tela, com opções de salvar no histórico e imprimir em PDF. A IA é uma avaliação preliminar e pode errar.</p>
  <details class="scan-details"><summary>Sobre a IA e os modelos</summary><p>A IA usa DINOv2 treinado no PlantVillage: maçã, mirtilo, cereja, milho, uva, laranja, pêssego, pimentão, batata, framboesa, soja, abóbora, morango e tomate. As imagens de treinamento mostram folhas isoladas; fotos de campo podem ter desempenho menor. Mirtilo, framboesa e soja têm apenas exemplos saudáveis no treinamento. Laranja e abóbora não têm classe saudável. A avaliação não cobre todas as doenças de cada cultura.</p><p>Modelo de Rodayna Emad Mohamed, licença CC BY-SA 4.0. <a class="link" href="https://huggingface.co/rodynaemad/plant-disease-dinov2-small" target="_blank" rel="noopener noreferrer">Ver modelo e limitações ↗</a></p><a class="link" href="#profile?model=files">Conectar meu próprio Teachable Machine</a></details>
 </form></section></div>`,'scan','Analisar planta');
}
function syncScanForm(){
 const form=$('#scan-form');if(!form)return;
 const method=form.elements.method.value;
 for(const note of form.querySelectorAll('[data-scan-method]'))note.hidden=note.dataset.scanMethod!==method;
 const button=$('#scan-submit');if(button&&!pendingForms.has('scan-form'))button.innerHTML=icon(method==='guided'?'file':'spark')+(method==='guided'?'Gerar relatório de observação':method==='teachable-machine'?'Analisar com meu modelo e gerar relatório':'Analisar com IA e gerar relatório');
 const observation=form.querySelector('[data-action="observation-report"]');if(observation)observation.hidden=method==='guided';
}
function draftKey(uid=state.user?.uid){return uid?'ecoplant-report-draft:'+uid:'';}
function rememberDraft(){try{const key=draftKey();if(key&&state.draft)sessionStorage.setItem(key,JSON.stringify({version:1,record:state.draft}));}catch{/* A blocked storage must not prevent the visible report. */}}
function forgetDraft(){try{const key=draftKey();if(key)sessionStorage.removeItem(key);}catch{}}
function restoreDraft(uid){
 try{const raw=sessionStorage.getItem(draftKey(uid));if(!raw||raw.length>500000)return;const saved=JSON.parse(raw),record=saved.record;
  if(saved.version!==1||!record||typeof record.id!=='string'||!photoSafe(record.photo)||!['plant-ai','guided','teachable-machine'].includes(record.result?.method))return;
  state.draft=record;state.scanPhoto=record.photo;state.scanPlantId=String(record.plantId||'');state.scanNotes=String(record.notes||'').slice(0,4000);state.scanSymptoms=Array.isArray(record.symptoms)?record.symptoms:[];state.scanMethod=record.result.method;
 }catch{/* Ignore an invalid draft and keep the rest of the application available. */}
}
function scanFailure(message,field){return Object.assign(new Error(message),{userMessage:message,field});}
async function generateScanReport(data,onProgress,signal){
 const photo=photoSafe(state.scanPhoto),plantId=String(data.get('plantId')||''),method=String(data.get('method')||'');
 if(!photo)throw scanFailure('Envie uma foto da folha antes de gerar o relatório.','#scan-image-button');
 if(plantId&&!findPlant(plantId))throw scanFailure('Escolha uma planta disponível ou use Somente esta foto.','[name="plantId"]');
 const notes=String(data.get('notes')||'').trim();if(notes.length>4000)throw scanFailure('Use até 4.000 caracteres nas observações.','[name="notes"]');
 const symptoms=data.getAll('symptom').filter(value=>SYMPTOMS.some(item=>item.id===value));
 let result;
 if(method==='guided')result=evaluateSymptoms(symptoms);
 else if(method==='plant-ai'||method==='teachable-machine'){
  const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(scanFailure('Não foi possível abrir esta foto. Selecione outra imagem.','#scan-image-button'));image.src=photo;});
  if(signal.aborted)throw Object.assign(new Error('Análise cancelada.'),{name:'AbortError'});
  if(method==='plant-ai')result=await classifyPlantAI(image,onProgress,{signal});
  else{
   const url=activeModelURL(),healthyClass=String(state.model?.source==='files'?state.model.healthyClass||'':state.profile.healthyClass||'');
   if(!url)throw scanFailure('Conecte seu treinamento no perfil ou escolha a IA pronta para usar.','#analysis-method');
   result=await classifyPlant(image,url,onProgress,{signal});
   if(result.severity!=='inconclusive'&&result.title!=='Análise inconclusiva'){
    const selected=healthyClass&&Array.isArray(result.modelLabels)&&result.modelLabels.includes(healthyClass);
    const healthy=Boolean(selected&&result.topClass===healthyClass);
    result={...result,title:healthy?'Classe saudável no modelo':'Classe identificada pelo modelo',summary:healthy?`O modelo escolheu “${result.topClass}”, a classe saudável selecionada para esta análise. A pontuação descreve a escolha do modelo e não confirma a saúde de toda a planta.`:`O modelo escolheu “${result.topClass}” entre as classes disponíveis.${selected?` A classe saudável selecionada nesta análise foi “${healthyClass}”.`:''} A classificação depende das imagens usadas no treinamento e não confirma um diagnóstico.`};
   }
  }
 }else throw scanFailure('Escolha IA de imagem ou Relatório de observação.','#analysis-method');
 const now=Date.now();return {id:uuid(),plantId,photo,date:now,symptoms,result,notes,createdAt:now,updatedAt:now};
}

function profileView(){const p=state.profile;return shell(`${heading('SEU ESPAÇO VERDE','Meu perfil','Seus dados, preferências e modelo de identificação.')}<div class="form-layout"><section class="panel form-panel"><div class="profile-header">${avatar()}<div><h2>${esc(name())}</h2><p>${esc(state.guest?'Conta local neste aparelho':state.user?.email||'Conta Google')}</p><label class="link" style="display:block;margin-top:7px;font-size:10px">Alterar foto<input type="file" accept="image/*" data-upload="profile" hidden></label></div></div><form id="profile-form">${field('Nome','displayName','Seu nome',{required:true,maxlength:120,value:p.displayName||p.name||state.user?.displayName||''})}${!state.guest?field('E-mail','profile-email','',{type:'email',value:state.user?.email||'',readonly:true}):''}<label class="checkbox"><input type="checkbox" name="reminders" ${p.reminders!==false?'checked':''}>Exibir lembretes de acompanhamento no aplicativo</label><button class="btn block" type="submit">${icon('check')}Salvar alterações</button><div class="form-error" role="alert"></div></form><div class="settings-list"><button class="setting" data-action="reset-password">${icon('lock')}Recuperar / alterar senha${icon('right')}</button><button class="setting" data-action="install">${icon('download')}Instalar no celular${icon('right')}</button><a class="setting" href="#guide">${icon('help')}Como usar o Ecoplant${icon('right')}</a><button class="setting" data-action="export-data">${icon('file')}Exportar meus registros${icon('right')}</button><button class="setting" data-action="logout" style="color:var(--red)">${icon('logout')}${state.guest?'Voltar para o login':'Sair da conta'}${icon('right')}</button></div></section>${modelSettingsView()}</div>`,'profile','Meu perfil');}
function guideView(){return shell(`${heading('UM GUIA PARA COMEÇAR','Cuidar, um passo de cada vez.','Conheça o caminho da primeira foto ao relatório da sua planta.')}<div class="form-layout"><section><div class="panel help-card"><h3>1. Adicione suas plantas</h3><p>Escolha um nome, informe a espécie e o local de cultivo e adicione uma foto. Cada planta terá seu próprio histórico.</p><a class="btn secondary small" href="#plant/new" style="margin-top:15px">Cadastrar planta</a></div><div class="panel help-card"><h3>2. Escolha como analisar</h3><p>Em <strong>Analisar planta</strong>, escolha <strong>IA de imagem — pronta para usar</strong>. O modelo será baixado no primeiro uso e processará a foto no próprio navegador. Use uma única folha bem iluminada, com fundo simples. A IA conhece 38 classes de 14 culturas e pode não reconhecer outras plantas.</p><p style="margin-top:12px">Para registrar a foto sem análise automática, escolha <strong>Relatório de observação — sem IA</strong>. Você pode acrescentar sinais e observações, mas eles são opcionais.</p><p style="margin-top:12px">Se já treinou um Teachable Machine, conecte o link ou os arquivos exportados em <strong>Meu perfil</strong> e escolha seu modelo na análise.</p><a class="btn secondary small" href="#scan" style="margin-top:15px">Analisar uma foto</a></div><div class="panel help-card"><h3>3. Fotografe e gere o relatório</h3><p>Abra a câmera ou envie uma imagem da galeria. Vincular a uma planta cadastrada é opcional. Toque no botão de gerar: o relatório aparece no aplicativo. Na ficha de uma planta, use <strong>Gerar relatório com esta foto</strong> para aproveitar a imagem cadastrada.</p></div><div class="panel help-card"><h3>4. Entenda o resultado</h3><p><strong>Aparência saudável:</strong> a folha se parece com os exemplos saudáveis do modelo. <strong>Sinais de possível doença ou praga:</strong> o relatório mostra a hipótese e o que observar. <strong>Análise inconclusiva:</strong> fotografe uma única folha com boa luz e tente novamente. A avaliação se refere à folha fotografada; não confirma a saúde de toda a planta.</p><p style="margin-top:12px">Salve os relatórios e faça novos registros ao longo dos dias. Na ficha da planta, use <strong>Comparar fotos</strong> para observar a primeira e a mais recente. No relatório, <strong>Imprimir / PDF</strong> permite exportar pelo navegador.</p></div></section><aside><div class="panel help-card"><h3>Instalar no Android</h3><p>Abra no Chrome e toque em <strong>Instalar aplicativo</strong>. Se a opção não aparecer, abra o menu de três pontos e escolha <strong>Instalar aplicativo</strong> ou <strong>Adicionar à tela inicial</strong>.</p><button class="btn secondary small" data-action="install" style="margin-top:15px">${icon('download')}Instalar Ecoplant</button></div><div class="panel help-card"><h3>Instalar no iPhone</h3><p>Abra o endereço no Safari. Toque em <strong>Compartilhar → Adicionar à Tela de Início → Adicionar</strong>. Ative <strong>Abrir como App da Web</strong>, quando disponível.</p></div><div class="panel help-card"><h3>Seus dados e suas fotos</h3><p>Na conta, os registros são sincronizados quando há internet. No modo <strong>Neste aparelho</strong>, os dados ficam apenas no navegador atual. Você pode exportá-los no perfil. Limpar os dados do navegador pode apagar os registros locais.</p></div><div class="notice">${icon('info')}<span>O Ecoplant apoia a observação. Uma classe identificada pelo modelo é uma hipótese e pode precisar de confirmação por um profissional.</span></div></aside></div>`,'guide','Como usar');}
function missing(){return shell(`${heading('MEU JARDIM','Registro não encontrado','Este item pode ter sido excluído ou pertencer a outra conta.')}<a class="btn" href="#plants">Voltar às plantas</a>`,'plants','Registro');}
function render(){
 const path=routePath();let html;
 const savedForms=lastRenderedRoute===currentRoute()?[...document.querySelectorAll('#plant-form, #profile-form, #model-form, #scan-form')].map(form=>({id:form.id,fields:[...form.querySelectorAll('[name]')].map(el=>({name:el.name,type:el.type,value:el.value,checked:el.checked,files:el.type==='file'?el.files:null})),focused:form.contains(document.activeElement)?document.activeElement.name:null})):[];
 if(!state.user){html=authScreen(['login','register','recover'].includes(path)?path:'login');}
 else if(path==='plants')html=plantsView();
 else if(path==='plant/new')html=plantForm();
 else if(/^plant\//.test(path)){const [,id,edit]=path.split('/');html=edit==='edit'?plantForm(id):plantDetail(id);}
 else if(path==='history')html=historyView();
 else if(path==='profile')html=profileView();
 else if(path==='scan')html=scanView();
 else if(path==='guide')html=guideView();
 else if(/^report\//.test(path)){const id=path.split('/')[1],record=id==='draft'?state.draft:state.analyses.find(a=>a.id===id);html=record?shell(reportHTML(record,findPlant(record.plantId),state.profile,{draft:id==='draft'}),'history','Relatório'):missing();}
 else html=home();
 $('#app').innerHTML=html;
 for(const saved of savedForms){const form=document.getElementById(saved.id);if(!form)continue;for(const el of form.querySelectorAll('[name]')){const prior=saved.fields.find(f=>f.name===el.name&&(el.type!=='checkbox'||f.value===el.value));if(!prior)continue;if(el.type==='checkbox'||el.type==='radio')el.checked=prior.checked;else if(el.type==='file'){if(prior.files?.length)try{el.files=prior.files;}catch{/* The user can select the files again if the browser restricts this. */}}else if(el.tagName==='SELECT'){if([...el.options].some(option=>option.value===prior.value&&!option.disabled))el.value=prior.value;}else el.value=prior.value;}if(saved.focused)[...form.querySelectorAll('[name]')].find(el=>el.name===saved.focused)?.focus({preventScroll:true});}
 syncModelSource();syncScanForm();
 for(const id of pendingForms){const submit=document.querySelector(`#${id} [type="submit"]`);if(submit){submit.disabled=true;submit.innerHTML=`${loaderHTML({small:true})} Só um instante…`;}}
 lastRenderedRoute=currentRoute();
}
async function loadGuest({destination=location.hash}={}){
 let uid=localStorage.getItem('ecoplant-guest-id');
 if(!uid){uid='local-'+uuid();localStorage.setItem('ecoplant-guest-id',uid);}
 unsubscribeData();state.guest=true;rememberAccessMode('local');
 if(state.user?.uid!==uid){modelLoadController?.abort();scanLoadController?.abort();clearImportedPlantModel();lastRenderedRoute='';Object.assign(state,blankData(),{model:null,scanPhoto:'',scanSymptoms:[],scanNotes:'',scanPlantId:'',scanMethod:'',draft:null,plantPhoto:null,profilePhoto:null});}
 state.user={uid,displayName:'Meu jardim',email:''};
 const data=await getCachedData(uid)||blankData();
 if(!state.guest||state.user?.uid!==uid)return;
 Object.assign(state,data,{source:'local',dataError:''});state.profile.displayName ||= 'Meu jardim';restoreDraft(uid);
 const requested=String(destination||'');
 const destinationPath=requested.slice(1).split('?')[0];
 const allowed=['home','plants','history','profile','scan','guide'].includes(destinationPath)||/^plant\/[A-Za-z0-9_-]+(?:\/edit)?$/.test(destinationPath)||/^report\/[A-Za-z0-9_-]+$/.test(destinationPath);
 const target=destinationPath==='report/draft'&&!state.draft?'#scan':allowed?requested:'#home';
 go(target);render();finishSplash();
}
async function persistLocal(data){const uid=state.user?.uid;if(!uid)throw Object.assign(new Error(),{userMessage:'Abra seu jardim para salvar o relatório.'});const stored=await putCachedData(uid,data);if(!stored)throw Object.assign(new Error(),{userMessage:'Este navegador bloqueou o armazenamento local. Permita os dados deste site para salvar seus registros.'});if(state.user?.uid!==uid)return;Object.assign(state,data);render();}
async function saveProfile(patch){if(state.guest){await persistLocal({...blankData(),profile:{...state.profile,...patch},plants:state.plants,analyses:state.analyses});}else{await cloud.saveProfile(state.user.uid,patch);state.profile={...state.profile,...patch};render();}}
async function savePlant(record){if(state.guest){await persistLocal({profile:state.profile,plants:[record,...state.plants.filter(p=>p.id!==record.id)],analyses:state.analyses});return record;}const saved=await cloud.savePlant(state.user.uid,record);state.plants=[saved,...state.plants.filter(p=>p.id!==saved.id)];return saved;}
async function saveAnalysis(record){const uid=state.user?.uid;if(!uid)throw Object.assign(new Error(),{userMessage:'Abra seu jardim para salvar o relatório.'});if(state.guest){await persistLocal({profile:state.profile,plants:state.plants,analyses:[record,...state.analyses.filter(a=>a.id!==record.id)]});return record;}const saved=await cloud.saveAnalysis(uid,record);if(state.user?.uid===uid&&!state.guest)state.analyses=[saved,...state.analyses.filter(a=>a.id!==saved.id)];return saved;}
async function activateUser(user){if(state.guest)return;if(user)rememberAccessMode('cloud');const userChanged=state.user?.uid!==user?.uid;unsubscribeData();if(userChanged){modelLoadController?.abort();scanLoadController?.abort();clearImportedPlantModel();lastRenderedRoute='';state.scanPhoto='';state.scanSymptoms=[];state.scanNotes='';state.draft=null;state.model=null;state.scanPlantId='';state.scanMethod='';state.plantPhoto=null;state.profilePhoto=null;}state.user=user;state.profile={};state.plants=[];state.analyses=[];state.dataError='';authResolved=true;if(!user){render();finishSplash();return;}state.profile.displayName=user.displayName||'';state.profile.email=user.email||'';if(userChanged)restoreDraft(user.uid);unsubscribeData=cloud.subscribeData(user.uid,data=>{if(state.user?.uid!==user.uid||state.guest)return;Object.assign(state,{...data,profile:{displayName:user.displayName||'',email:user.email||'',...data.profile},dataError:''});render();},error=>{state.dataError=errorMessage(error);render();});if(['login','register','recover',''].includes(routePath()))go('#home');render();finishSplash();try{if(cloud.ensureProfile)await cloud.ensureProfile(user);}catch(error){state.dataError=errorMessage(error);render();}}
async function resizeImage(file){if(!file||file.size>15*1024*1024)throw new Error('Escolha uma imagem de até 15 MB.');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('Este formato não abriu no navegador. Use uma foto JPG, PNG ou WebP.'));img.src=url;});return canvasPhoto(img);}finally{URL.revokeObjectURL(url);}}
function canvasPhoto(source){const width=source.videoWidth||source.naturalWidth||source.width,height=source.videoHeight||source.naturalHeight||source.height;if(!width||!height)throw new Error('A câmera ainda está preparando a imagem. Tente novamente.');const scale=Math.min(1,850/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.round(width*scale);canvas.height=Math.round(height*scale);canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);let q=.82,data=canvas.toDataURL('image/jpeg',q);while(data.length>230000&&q>.25){q-=.08;data=canvas.toDataURL('image/jpeg',q);}if(data.length>240000)throw new Error('A imagem ficou muito grande. Aproxime-se de uma única folha e tente de novo.');return data;}
function stopCamera(){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;}
async function openCamera(){const d=openDialog('Fotografar uma folha',`<div class="camera-view"><video id="camera-video" autoplay playsinline muted style="display:block;width:100%;aspect-ratio:1;object-fit:cover;border-radius:13px;background:#173e32"></video><p class="privacy-note" style="margin:12px 0">Uma folha por vez. Mantenha a câmera firme e use boa iluminação.</p><div class="form-actions"><button class="btn" data-action="capture-photo">${icon('camera')}Fotografar</button><button class="btn secondary" data-action="flip-camera" aria-label="Alternar câmera">${icon('switch')}</button></div><div id="camera-message" class="form-error" role="alert"></div></div>`);try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Câmera indisponível neste navegador.');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:cameraFacing},width:{ideal:1280},height:{ideal:1280}},audio:false});if(!d.open){stream.getTracks().forEach(t=>t.stop());return;}cameraStream=stream;const v=$('#camera-video');v.srcObject=stream;await v.play();}catch(error){stopCamera();const m=$('#camera-message');if(m)m.innerHTML=`${esc(error.name==='NotAllowedError'?'Permita o acesso à câmera nas configurações do navegador ou use uma foto da galeria.':error.message||'Não foi possível abrir a câmera.')}<br><button class="link" data-action="camera-file" style="margin-top:10px">Usar câmera do aparelho / galeria</button>`;}}
function getCurrentReport(){return routePath()==='report/draft'?state.draft:state.analyses.find(a=>a.id===routePath().split('/')[1]);}
async function install(){const result=await installApp();if(result.installed){toast('Ecoplant instalado. Encontre o ícone na tela inicial.');return;}if(result.dismissed||result.outcome==='dismissed')return;const instructions=Array.isArray(result.instructions)?result.instructions:[result.instructions||'Abra o menu do navegador e escolha Instalar aplicativo ou Adicionar à tela inicial.'];openDialog(isStandalone()?'Ecoplant no seu aparelho':'Instalar Ecoplant',`<p class="dialog-copy">${isStandalone()?'Você já está usando o aplicativo pela tela inicial.':'Tenha seu jardim a um toque de distância.'}</p><ol class="install-steps">${instructions.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><button class="btn block" data-action="close-dialog">Entendi</button>`);}
function downloadJSON(data,filename){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;
 const loadingActions={google:'Conectando sua conta Google…','confirm-reset':'Enviando o link de recuperação…','retry-sync':'Sincronizando seu jardim…','save-report':'Salvando seu relatório…','confirm-delete-plant':'Excluindo a planta e os registros…','confirm-delete-report':'Excluindo o relatório…',guest:'Abrindo seu jardim neste aparelho…'};
 const clickLoadingToken=loadingActions[action]?showLoading(loadingActions[action]):null;
 try{
  if(action==='toggle-password'){const input=document.getElementById(b.dataset.target);input.type=input.type==='password'?'text':'password';b.setAttribute('aria-label',input.type==='password'?'Mostrar senha':'Ocultar senha');return;}
  if(action==='close-dialog'){closeDialog();return;}
  if(action==='guest'){await loadGuest({destination:b.dataset.destination||location.hash});return;}
  if(action==='install'){await install();return;}
  if(action==='google'){rememberAccessMode('cloud');b.disabled=true;const remember=$('[name="remember"]')?.checked!==false;try{await cloud.loginGoogle(remember);}finally{if(b.isConnected)b.disabled=false;}return;}
  if(action==='choose-photo'){const id=b.dataset.target;if(['plant-photo-input','scan-photo-input'].includes(id))document.getElementById(id)?.click();return;}
  if(action==='retry-analysis'){$('#scan-form')?.requestSubmit();return;}
  if(action==='observation-report'){const form=$('#scan-form');if(form){form.elements.method.value='guided';state.scanMethod='guided';syncScanForm();form.requestSubmit();}return;}
  if(action==='analyze-plant-photo'){const plant=findPlant(id);if(!photoSafe(plant?.photo))throw scanFailure('Esta planta ainda não tem uma foto. Envie uma imagem para analisar.');state.scanPhoto=plant.photo;state.scanPlantId=id;state.scanSymptoms=[];state.scanNotes='';state.scanMethod='plant-ai';go('#scan?plant='+encodeURIComponent(id));return;}
  if(action==='new-plant-analysis'){state.scanPhoto='';state.scanPlantId=findPlant(id)?id:'';state.scanSymptoms=[];state.scanNotes='';state.scanMethod='plant-ai';go('#scan?plant='+encodeURIComponent(state.scanPlantId));return;}
  if(action==='open-camera'){await openCamera();return;}
  if(action==='flip-camera'){cameraFacing=cameraFacing==='environment'?'user':'environment';closeDialog();await openCamera();return;}
  if(action==='capture-photo'){state.scanPhoto=canvasPhoto($('#camera-video'));closeDialog();render();return;}
  if(action==='camera-file'){closeDialog();$('#camera-fallback')?.click();return;}
  if(action==='remove-plant-photo'){state.plantPhoto='';render();return;}
  if(action==='logout'){rememberAccessMode('login');unsubscribeData();stopCamera();modelLoadController?.abort();scanLoadController?.abort();forgetDraft();clearImportedPlantModel();clearPlantAI();const wasGuest=state.guest;state.guest=false;state.user=null;lastRenderedRoute='';Object.assign(state,blankData(),{dataError:'',model:null,scanPhoto:'',scanSymptoms:[],scanNotes:'',scanPlantId:'',scanMethod:'',draft:null});if(!wasGuest)await cloud.logout();go('#login');render();return;}
  if(action==='retry-sync'){state.dataError='';if(!state.guest)await activateUser(state.user);return;}
  if(action==='reset-password'){if(state.guest){toast('Entre em uma conta para recuperar a senha.');return;}openDialog('Alterar sua senha',`<p class="dialog-copy">Vamos enviar um link de recuperação para <strong>${esc(state.user.email||'seu e-mail')}</strong>. Se você entra com Google, sua senha é gerenciada pela conta Google.</p><button class="btn block" data-action="confirm-reset">Enviar link de recuperação</button>`);return;}
  if(action==='confirm-reset'){b.disabled=true;await cloud.recover(state.user.email);closeDialog();toast('Se o e-mail estiver cadastrado para senha, você receberá o link.');return;}
  if(action==='remove-model'){await saveProfile({modelURL:'',healthyClass:''});clearImportedPlantModel();state.model=null;const form=$('#model-form');if(form){form.elements.modelSource.value=MODEL_CONFIG.bundledModelAvailable?'bundled':'files';form.elements.modelURL.value='';form.elements.healthyClass.value='';form.elements.modelFiles.value='';}state.scanMethod='';toast(MODEL_CONFIG.bundledModelAvailable?'Modelo do EcoPlant selecionado.':'Modelo desconectado. Você pode carregar outro modelo no perfil.');render();return;}
  if(action==='export-data'){downloadJSON({app:'Ecoplant',exportedAt:new Date().toISOString(),profile:state.profile,plants:state.plants,analyses:state.analyses},'ecoplant-meu-jardim.json');return;}
  if(action==='delete-plant'){openDialog('Excluir esta planta?',`<p class="dialog-copy">${esc(findPlant(id)?.name)} e os relatórios vinculados serão excluídos. Esta ação não pode ser desfeita.</p><button class="btn danger block" data-action="confirm-delete-plant" data-id="${esc(id)}">${icon('trash')}Excluir planta e relatórios</button>`);return;}
  if(action==='confirm-delete-plant'){b.disabled=true;const records=state.analyses.filter(a=>a.plantId===id);if(state.guest){await persistLocal({profile:state.profile,plants:state.plants.filter(p=>p.id!==id),analyses:state.analyses.filter(a=>a.plantId!==id)});}else{for(const a of records)await cloud.deleteAnalysis(state.user.uid,a.id);await cloud.deletePlant(state.user.uid,id);state.plants=state.plants.filter(p=>p.id!==id);state.analyses=state.analyses.filter(a=>a.plantId!==id);}closeDialog();go('#plants');toast('Planta excluída.');return;}
  if(action==='save-report'){if(!state.draft)return;const uid=state.user?.uid,draft=state.draft;b.disabled=true;const record=await saveAnalysis(draft);if(state.user?.uid!==uid||state.draft?.id!==draft.id)return;forgetDraft();state.draft=null;go('#report/'+record.id);toast(state.guest?'Relatório salvo neste aparelho.':'Relatório salvo na sua conta.');return;}
  if(action==='export-report'){const a=getCurrentReport();if(!a)return;const plant=findPlant(a.plantId);openDialog('Exportar relatório',`<p class="dialog-copy">${esc(plant?.name||'Sua planta')} · ${date(a.date||a.createdAt)}<br>O relatório continua disponível aqui no aplicativo. Escolha como deseja exportar.</p><div style="display:grid;gap:12px"><button class="btn block" data-action="print-report">${icon('file')}PDF · salvar ou imprimir</button><button class="btn secondary block" data-action="download-report">${icon('download')}JSON · exportar os dados</button></div><p class="privacy-note" style="margin-top:16px">Para PDF, escolha Salvar como PDF ou Compartilhar na janela de impressão do aparelho.</p>`);return;}
  if(action==='print-report'){if($('#dialog').open)closeDialog();window.print();return;}
  if(action==='download-report'){const a=getCurrentReport();if(a)downloadReport(a,findPlant(a.plantId));if($('#dialog').open)closeDialog();return;}
  if(action==='delete-report'){const a=getCurrentReport();if(!a)return;openDialog('Excluir este relatório?',`<p class="dialog-copy">O registro de ${date(a.date)} será excluído do histórico.</p><button class="btn danger block" data-action="confirm-delete-report" data-id="${esc(a.id)}">Excluir relatório</button>`);return;}
  if(action==='confirm-delete-report'){if(state.guest)await persistLocal({profile:state.profile,plants:state.plants,analyses:state.analyses.filter(a=>a.id!==id)});else await cloud.deleteAnalysis(state.user.uid,id);closeDialog();go('#history');toast('Relatório excluído.');return;}
  if(action==='compare'){const records=sortedAnalyses().filter(a=>a.plantId===id&&photoSafe(a.photo));if(records.length<2){toast('Adicione pelo menos duas fotos para comparar.');return;}const old=records.at(-1),recent=records[0];openDialog('Evolução da planta',`<p class="dialog-copy">${esc(findPlant(id)?.name||'Sua planta')} · Compare os registros visuais. As fotos não medem a gravidade da condição.</p><div class="compare-grid"><section><img src="${esc(old.photo)}" alt="Primeira foto"><p>Primeira foto · ${date(old.date)}</p></section><section><img src="${esc(recent.photo)}" alt="Foto mais recente"><p>Mais recente · ${date(recent.date)}</p></section></div>`);return;}
 }catch(error){if(b.isConnected)b.disabled=false;toast(errorMessage(error),true);}
 finally{if(clickLoadingToken!==null)hideLoading(clickLoadingToken);}
});
document.addEventListener('submit',async e=>{
 const operationUID=state.user?.uid;const form=e.target;if(!['auth-form','plant-form','profile-form','model-form','scan-form'].includes(form.id))return;e.preventDefault();if(pendingForms.has(form.id))return;pendingForms.add(form.id);
 const operationController=['scan-form','model-form'].includes(form.id)?new AbortController():null;
 if(form.id==='scan-form'){scanLoadController?.abort();scanLoadController=operationController;}
 if(form.id==='model-form'){modelLoadController?.abort();modelLoadController=operationController;}
 let cancelledByUser=false;
 const loadingToken=showLoading(form.id==='scan-form'?'Preparando o relatório da planta…':form.id==='model-form'?'Conectando seu modelo…':form.id==='auth-form'?'Conectando sua conta…':'Salvando seu jardim…',operationController?{onCancel:()=>{cancelledByUser=true;operationController.abort();}}:{});
 const data=new FormData(form),button=form.querySelector('[type="submit"]'),original=button?.innerHTML,err=form.querySelector('.form-error');if(err)err.textContent='';form.querySelector('#model-recovery')?.classList.add('hidden');if(button){button.disabled=true;button.innerHTML=`${loaderHTML({small:true})} Só um instante…`;}
 try{
  if(form.id==='auth-form'){if(form.dataset.view!=='recover')rememberAccessMode('cloud');const view=form.dataset.view,email=data.get('email'),password=data.get('password'),remember=data.get('remember')==='on';if(view==='register'){if(password!==data.get('confirm'))throw Object.assign(new Error(),{userMessage:'As senhas precisam ser iguais.'});await cloud.register(data.get('name'),email,password,remember);}else if(view==='recover'){await cloud.recover(email);openDialog('Confira sua caixa de entrada',`<p class="dialog-copy">Se o e-mail estiver cadastrado, você receberá um link para redefinir sua senha. Confira também o spam.</p><button class="btn block" data-action="close-dialog">Entendi</button>`);}else await cloud.login(email,password,remember);}
  if(form.id==='plant-form'){const old=findPlant(form.dataset.id),record={id:old?.id||uuid(),name:String(data.get('plant-name')).trim(),species:String(data.get('species')||'').trim(),location:String(data.get('location')||'').trim(),notes:String(data.get('notes')||'').trim(),photo:state.plantPhoto??old?.photo??'',createdAt:old?.createdAt||Date.now(),updatedAt:Date.now()};if(!record.name)throw Object.assign(new Error(),{userMessage:'Informe o nome da planta.'});await savePlant(record);state.plantPhoto=null;go('#plant/'+record.id);toast(state.guest?'Planta salva neste aparelho.':'Planta salva no seu jardim.');}
  if(form.id==='profile-form'){const displayName=String(data.get('displayName')||'').trim();if(!state.guest)await cloud.updateUserProfile({displayName});await saveProfile({displayName,reminders:data.get('reminders')==='on',...(state.profilePhoto?{photo:state.profilePhoto}:{})});state.profilePhoto=null;toast('Seu perfil foi atualizado.');}
  if(form.id==='model-form'){
   const source=String(data.get('modelSource')||'bundled'),healthyClass=String(data.get('healthyClass')||'').trim();
   const controller=operationController;
   const progress=msg=>{updateLoading(msg,loadingToken);if(button?.isConnected)button.textContent=msg;};
   const info=source==='files'
    ?await loadPlantModelFromFiles(form.elements.modelFiles.files,progress,{signal:controller.signal,healthyClass})
    :await loadPlantModel(source==='bundled'?BUNDLED_MODEL_URL:validateModelURL(data.get('modelURL')),progress,{signal:controller.signal});
   if(healthyClass&&!info.labels.includes(healthyClass))throw Object.assign(new Error(),{userMessage:'A classe saudável precisa ter o mesmo nome de uma das classes do modelo: '+info.labels.join(', ')});
   if(controller.signal.aborted||state.user?.uid!==operationUID)return;
   if(source==='files'){state.model={...info,healthyClass};}
   else{await saveProfile({modelURL:source==='hosted'?info.modelURL:'',healthyClass});if(controller.signal.aborted||state.user?.uid!==operationUID)return;clearImportedPlantModel();state.model={...info,healthyClass};}
   state.scanMethod='teachable-machine';render();toast(source==='files'?'Modelo carregado nesta aba. Você já pode analisar uma foto.':'Modelo validado e conectado.');
  }
  if(form.id==='scan-form'){
   const controller=operationController;
   const record=await generateScanReport(data,msg=>{updateLoading(msg,loadingToken);if(button?.isConnected)button.textContent=msg;},controller.signal);
   if(controller.signal.aborted||state.user?.uid!==operationUID)return;
   state.scanNotes=record.notes;state.scanSymptoms=record.symptoms;state.scanMethod=record.result.method;state.scanPlantId=record.plantId;state.draft=record;rememberDraft();scanLoadController=null;
   go('#report/draft');render();window.scrollTo({top:0,behavior:'instant'});toast('Relatório gerado. Você já pode ler e salvar em PDF.');
  }
 }catch(error){
  if(cancelledByUser){toast(form.id==='scan-form'?'Análise cancelada. Sua foto e observações foram mantidas.':'Carregamento cancelado. Você pode tentar novamente.');return;}
  if(error?.name==='AbortError'&&((form.id==='scan-form'&&routePath()!=='scan')||(form.id==='model-form'&&routePath()!=='profile')))return;
  const message=errorMessage(error),visibleError=document.querySelector(`#${form.id} .form-error`);
  if(visibleError){visibleError.textContent=message;visibleError.scrollIntoView({behavior:'smooth',block:'center'});visibleError.focus?.({preventScroll:true});}else toast(message,true);
  if(form.id==='scan-form'){
   const recovery=$('#model-recovery');recovery?.classList.remove('hidden');const tmLink=recovery?.querySelector('[data-tm-recovery]');if(tmLink)tmLink.hidden=state.scanMethod!=='teachable-machine';
   if(error.field)document.querySelector(error.field)?.focus({preventScroll:true});
  }
 }finally{
  if(form.id==='model-form'&&modelLoadController===operationController)modelLoadController=null;if(form.id==='scan-form'&&scanLoadController===operationController)scanLoadController=null;
  hideLoading(loadingToken);pendingForms.delete(form.id);const current=document.querySelector(`#${form.id} [type="submit"]`);if(current){current.disabled=false;current.innerHTML=original;}syncScanForm();
 }
});
document.addEventListener('change',async e=>{
 const input=e.target;
 if(input.id==='model-source'){syncModelSource();return;}
 if(input.matches('[data-upload]')){if(!input.files?.[0])return;try{const image=await resizeImage(input.files[0]);if(input.dataset.upload==='scan'){state.scanPhoto=image;}else if(input.dataset.upload==='plant'){// Preserve typed fields while repainting the photograph.
 const form=$('#plant-form'),values=form?new FormData(form):null;state.plantPhoto=image;render();if(values)for(const [key,val] of values){const element=$(`[name="${key}"]`);if(element&&typeof val==='string')element.value=val;}$('#plant-image-button')?.focus({preventScroll:true});return;
 }else{state.profilePhoto=image;await saveProfile({photo:image});state.profilePhoto=null;toast('Foto do perfil atualizada.');}render();if(input.dataset.upload==='scan')$('#scan-image-button')?.focus({preventScroll:true});}catch(error){toast(error.message||'Não foi possível abrir a imagem.',true);}return;}
 if(input.name==='plantId')state.scanPlantId=input.value;
 if(input.id==='analysis-method'){state.scanMethod=input.value;syncScanForm();}
 if(input.id==='history-filter'||input.id==='history-health-filter')filterHistory();
 if(input.name==='symptom'){const boxes=[...document.querySelectorAll('[name="symptom"]')];if(input.value==='healthy'&&input.checked)boxes.filter(b=>b!==input).forEach(b=>b.checked=false);else if(input.checked)boxes.find(b=>b.value==='healthy')?.removeAttribute('checked');const healthy=boxes.find(b=>b.value==='healthy');if(input.value!=='healthy'&&input.checked&&healthy)healthy.checked=false;state.scanSymptoms=boxes.filter(b=>b.checked).map(b=>b.value);}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){const q=e.target.value.toLocaleLowerCase('pt-BR').trim();let count=0;document.querySelectorAll('[data-plant-search]').forEach(el=>{el.hidden=!el.dataset.plantSearch.includes(q);if(!el.hidden)count++;});$('#search-empty')?.classList.toggle('hidden',count>0);}if(e.target.matches('#scan-form textarea'))state.scanNotes=e.target.value;});
window.addEventListener('hashchange',()=>{stopCamera();if(routePath()!=='scan')scanLoadController?.abort();if($('#dialog').open)$('#dialog').close();state.plantPhoto=null;if(routePath()==='scan'&&routeParams().get('plant')){const plantId=routeParams().get('plant');if(plantId!==state.scanPlantId){state.scanPhoto='';state.scanSymptoms=[];state.scanNotes='';}state.scanPlantId=plantId;}render();window.scrollTo({top:0,behavior:'instant'});});
$('#dialog').addEventListener('close',stopCamera);
initPWA({onOnlineChange:()=>render(),onUpdateAvailable:()=>{openDialog('Uma nova folha por aqui',`<p class="dialog-copy">Há uma nova versão do Ecoplant. Salve seus registros antes de atualizar.</p><button class="btn block" data-action="update-app">Atualizar aplicativo</button>`);}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="update-app"]'))applyUpdate();});
render();
// A chosen local garden takes precedence over a cached Firebase login. Its UID
// and records remain separate; returning to the login clears this preference.
if(accessMode()==='local'&&!/^#(?:login|register|recover)(?:\?|$)/.test(location.hash)){
 void loadGuest({destination:location.hash}).catch(error=>{state.guest=false;state.user=null;rememberAccessMode('login');render();finishSplash();toast(errorMessage(error),true);});
}else{
 // The sign-in screen and the no-account entry are ready without waiting for
 // a slow Firebase connection. Authentication can restore in the background.
 finishSplash();
}
cloud.subscribeAuth(activateUser,error=>{authResolved=true;finishSplash();console.warn('Ecoplant: autenticação indisponível.',error?.code||'network');});

cloud.ready.then(result=>{if(!result.ok)finishSplash();});
